<?php
declare(strict_types=1);
namespace Kios\MerchantOperations;
use PDO;use Throwable;use DomainException;use InvalidArgumentException;
use Kios\MerchantFoundation\{AuthenticatedUserProvider,TenantContext,PdoIdentityStore,Identity};
use Kios\Infrastructure\Environment;
/** Nonfinancial snapshots only. No payment, order mutation, inventory or table-release dependency. */
final class BillDrafts {
 public function __construct(private PDO $db,private AuthenticatedUserProvider $auth){}
 private function rows(string $s,array $p=[]):array{$q=$this->db->prepare($s);$q->execute($p);return $q->fetchAll(PDO::FETCH_ASSOC);}
 private function transaction(string $m,string $o,callable $fn):mixed{
  if(Environment::get('APP_ENV')!=='demo'||Environment::get('KIOS_BILL_DRAFTS_ENABLED','0')!=='1')throw new DomainException('Bill demonstration disabled.');
  if($this->db->inTransaction())throw new \LogicException('Billing owns transaction.');
  for($attempt=1;$attempt<=3;$attempt++){
  $c=TenantContext::resolve($this->auth,new PdoIdentityStore($this->db),$m,$o);
  $this->db->exec('SET TRANSACTION ISOLATION LEVEL READ COMMITTED');$this->db->beginTransaction();
  try{
   if($this->auth->currentUserId()!==$c->userId)throw new DomainException('Current staff identity required.');
   $roles=array_column($this->rows('SELECT role_code FROM merchant_memberships WHERE merchant_id=? AND user_id=? AND active=1 FOR UPDATE',[$m,$c->userId]),'role_code');
   $roles=array_merge($roles,array_column($this->rows('SELECT role_code FROM merchant_outlet_memberships WHERE merchant_id=? AND outlet_id=? AND user_id=? AND active=1 FOR UPDATE',[$m,$o,$c->userId]),'role_code'));
   if(!array_intersect($roles,['merchant_owner','outlet_administrator','cashier']))throw new DomainException('Billing staff permission required.');
   $maps=$this->rows("SELECT l.legacy_outlet_id FROM merchant_outlets o JOIN merchant_organizations m ON m.merchant_id=o.merchant_id AND m.active=1 JOIN merchant_onboarding onboard ON onboard.merchant_id=o.merchant_id AND onboard.status='active' JOIN merchant_legacy_outlets l ON l.merchant_id=o.merchant_id AND l.merchant_outlet_id=o.outlet_id JOIN outlets lo ON lo.outlet_id=l.legacy_outlet_id AND lo.active=1 WHERE o.merchant_id=? AND o.outlet_id=? AND o.active=1 FOR UPDATE",[$m,$o]);if(count($maps)!==1)throw new DomainException('Active outlet required.');
   (new Entitlements($this->db,$this->auth))->requireFeature($m,$o,'billing');$r=$fn($c,(int)$maps[0]['legacy_outlet_id'],(bool)array_intersect($roles,['merchant_owner','outlet_administrator']));$this->db->commit();return $r;
  }catch(Throwable $e){if($this->db->inTransaction())$this->db->rollBack();if($e instanceof \PDOException && in_array((int)($e->errorInfo[1]??0),[1213,1205],true) && $attempt<3){usleep(10000*$attempt);continue;}throw $e;}
  }
 }
 private function source(string $m,string $o,string $service,int $legacy):array{
  Identity::validate($service);$s=$this->rows("SELECT s.*,t.name table_name,f.name floor_name FROM merchant_service_sessions s JOIN merchant_seating_tables t ON t.merchant_id=s.merchant_id AND t.outlet_id=s.outlet_id AND t.table_id=s.table_id JOIN merchant_seating_floors f ON f.merchant_id=t.merchant_id AND f.outlet_id=t.outlet_id AND f.floor_id=t.floor_id WHERE s.merchant_id=? AND s.outlet_id=? AND s.service_id=? AND s.legacy_outlet_id=? AND s.status IN ('SUBMITTED','SERVED') FOR UPDATE",[$m,$o,$service,$legacy]);if(count($s)!==1)throw new DomainException('Select an authorized submitted internal service.');$s=$s[0];
  $order=$this->rows("SELECT order_id,status,total_paise FROM orders WHERE outlet_id=? AND order_id=? AND order_mode='INTERNAL_SERVICE' FOR UPDATE",[$legacy,$s['order_id']]);if(count($order)!==1)throw new DomainException('Internal order required.');
  $items=$this->rows('SELECT order_item_id,product_name_snapshot,variant_label_snapshot,unit_snapshot,quantity,unit_price_paise,line_total_paise FROM order_items WHERE outlet_id=? AND order_id=? ORDER BY order_item_id FOR UPDATE',[$legacy,$s['order_id']]);if(!$items||count($items)>50)throw new DomainException('Unsupported order size.');$total=0;foreach($items as $i){$q=self::number((string)$i['quantity'],1,99);$p=self::number((string)$i['unit_price_paise'],0,100000000);if($q*$p!==(int)$i['line_total_paise'])throw new DomainException('Inconsistent source pricing.');$total+=$q*$p;}if($total>100000000||$total!==(int)$order[0]['total_paise'])throw new DomainException('Unsupported or inconsistent total.');
  $data=['service'=>$service,'serviceVersion'=>(int)$s['version'],'order'=>$order[0],'table'=>$s['table_id'],'tableName'=>$s['table_name'],'floorName'=>$s['floor_name'],'items'=>$items,'subtotal'=>$total];return ['hash'=>hash('sha256',json_encode($data,JSON_THROW_ON_ERROR)),'data'=>$data];
 }
 public static function number(mixed $v,int $min,int $max):int{if(!is_string($v)||!preg_match('/^(0|[1-9][0-9]{0,8})$/D',$v)||(int)$v<$min||(int)$v>$max)throw new InvalidArgumentException('Use bounded whole numbers. Monetary input is in paise.');return (int)$v;}
 public static function calculate(array $source,string $mode,string $people,string $discount,string $reason,array $allocation):array{
  $n=self::number($people,1,20);$off=self::number($discount,0,$source['subtotal']);if(!mb_check_encoding($reason,'UTF-8')||mb_strlen($reason)>240||preg_match('/[<>\x00-\x1f\x7f]/u',$reason)||($off>0&&trim($reason)===''))throw new InvalidArgumentException('Enter a short plain-text adjustment reason.');$total=$source['subtotal']-$off;$raw=array_fill(0,$n,0);
  if($mode==='equal'){if($allocation!==[])throw new InvalidArgumentException('Equal split has no item allocations.');$portions=array_fill(0,$n,intdiv($total,$n));for($i=0;$i<$total%$n;$i++)$portions[$i]++;}
  elseif($mode==='items'){$ids=array_map(fn($i)=>(string)$i['order_item_id'],$source['items']);if(count($allocation)!==count($ids)||array_diff(array_map('strval',array_keys($allocation)),$ids))throw new InvalidArgumentException('Allocate every source item once.');foreach($source['items']as $item){$qs=$allocation[(string)$item['order_item_id']]??null;if(!is_array($qs)||!array_is_list($qs)||count($qs)!==$n)throw new InvalidArgumentException('Every portion needs a quantity.');$sum=0;foreach($qs as $i=>$q){$q=self::number($q,0,(int)$item['quantity']);$sum+=$q;$raw[$i]+=$q*(int)$item['unit_price_paise'];}if($sum!==(int)$item['quantity'])throw new InvalidArgumentException('Allocation must equal each ordered quantity.');}$portions=[];foreach($raw as $v)$portions[]=$source['subtotal']?intdiv($total*$v,$source['subtotal']):0;$remainder=$total-array_sum($portions);for($i=0;$remainder>0;$i=($i+1)%$n)if($raw[$i]>0){$portions[$i]++;$remainder--;}}
  else throw new InvalidArgumentException('Select equal or item split.');
  if(array_sum($portions)!==$total)throw new \LogicException('Portions do not reconcile.');return ['source'=>$source,'mode'=>$mode,'people'=>$n,'discount'=>$off,'adjustmentType'=>$off?'DISCOUNT':'NONE','reason'=>trim($reason),'allocation'=>$allocation,'total'=>$total,'portions'=>$portions,'currency'=>'INR','notice'=>'DEMONSTRATION — NOT A RECEIPT OR TAX INVOICE'];
 }
 public function save(string $m,string $o,string $request,string $service,string $version,string $sourceHash,string $mode,string $people,string $discount,string $reason,array $allocation,bool $cancel=false):array{
  return $this->transaction($m,$o,function($c,$legacy,$manager)use($m,$o,$request,$service,$version,$sourceHash,$mode,$people,$discount,$reason,$allocation,$cancel){
   if(!preg_match('/^[a-f0-9]{32}$/D',$request))throw new InvalidArgumentException('Reload request form.');$payload=hash('sha256',json_encode([$service,$version,$sourceHash,$mode,$people,$discount,$reason,$allocation,$cancel],JSON_THROW_ON_ERROR));
   $prior=$this->rows('SELECT * FROM merchant_bill_revisions WHERE request_id=? FOR UPDATE',[$request]);if($prior){$p=$prior[0];if($p['merchant_id']!==$m||$p['outlet_id']!==$o||$p['actor_id']!==$c->userId||!hash_equals($p['payload_hash'],$payload))throw new DomainException('Request key conflict.');return ['bill'=>$p['bill_id'],'version'=>(int)$p['version']];}
   $src=$this->source($m,$o,$service,$legacy);if(!hash_equals($src['hash'],$sourceHash))throw new DomainException('Source order changed. Reload and explicitly review current snapshots.');
   $old=$this->rows('SELECT * FROM merchant_bill_drafts WHERE merchant_id=? AND outlet_id=? AND service_id=? FOR UPDATE',[$m,$o,$service]);$old=$old[0]??null;if((string)($old['version']??0)!==$version||($old&&$old['status']!=='DRAFT'))throw new DomainException('Draft changed or cancelled. Reload.');
   if(!$manager&&(int)$discount!==(int)($old?json_decode($old['snapshot_json'],true)['discount']:0))throw new DomainException('Only owner or outlet administrator can change draft discounts.');
   $snapshot=self::calculate($src['data'],$mode,$people,$discount,$reason,$allocation);if($cancel&&!$old)throw new DomainException('Save before cancelling.');$id=$old['bill_id']??Identity::generate();$v=(int)$version+1;$status=$cancel?'CANCELLED':'DRAFT';$json=json_encode($snapshot,JSON_THROW_ON_ERROR);
   if(!$old)$this->rows('INSERT INTO merchant_bill_drafts VALUES(?,?,?,?,?,?,?,?)',[$m,$o,$id,$service,$v,$status,$src['hash'],$json]);
   else $this->rows('UPDATE merchant_bill_drafts SET version=?,status=?,source_hash=?,snapshot_json=? WHERE merchant_id=? AND outlet_id=? AND bill_id=?',[$v,$status,$src['hash'],$json,$m,$o,$id]);
   $this->rows('INSERT INTO merchant_bill_revisions VALUES(?,?,?,?,?,?,?,?,?,?)',[$m,$o,$id,$v,$request,$c->userId,$cancel?'cancel':($old?'revise':'create'),$payload,$json,time()]);return ['bill'=>$id,'version'=>$v];
  });
 }
 public function load(string $m,string $o,string $service=''):array{return $this->transaction($m,$o,function($c,$legacy,$manager)use($m,$o,$service){$services=$this->rows("SELECT s.service_id,s.order_id,t.name table_name,f.name floor_name,s.status FROM merchant_service_sessions s JOIN merchant_seating_tables t ON t.merchant_id=s.merchant_id AND t.outlet_id=s.outlet_id AND t.table_id=s.table_id JOIN merchant_seating_floors f ON f.merchant_id=t.merchant_id AND f.outlet_id=t.outlet_id AND f.floor_id=t.floor_id WHERE s.merchant_id=? AND s.outlet_id=? AND s.status IN ('SUBMITTED','SERVED') ORDER BY s.created_epoch DESC LIMIT 200",[$m,$o]);$drafts=$this->rows('SELECT * FROM merchant_bill_drafts WHERE merchant_id=? AND outlet_id=? ORDER BY bill_id LIMIT 200',[$m,$o]);$source=$service!==''?$this->source($m,$o,$service,$legacy):null;$draft=null;foreach($drafts as $d)if($d['service_id']===$service)$draft=$d;$history=$draft?$this->rows('SELECT version,actor_id,operation,occurred_epoch,snapshot_json FROM merchant_bill_revisions WHERE merchant_id=? AND outlet_id=? AND bill_id=? ORDER BY version DESC',[$m,$o,$draft['bill_id']]):[];return ['outlets'=>$this->rows("SELECT o.outlet_id,o.name FROM merchant_outlets o WHERE o.merchant_id=? AND o.active=1 AND (EXISTS(SELECT 1 FROM merchant_memberships r WHERE r.merchant_id=o.merchant_id AND r.user_id=? AND r.active=1 AND r.role_code='merchant_owner') OR EXISTS(SELECT 1 FROM merchant_outlet_memberships r WHERE r.merchant_id=o.merchant_id AND r.outlet_id=o.outlet_id AND r.user_id=? AND r.active=1 AND r.role_code IN ('cashier','outlet_administrator'))) ORDER BY o.name",[$m,$c->userId,$c->userId]),'merchant'=>$m,'outlet'=>$o,'services'=>$services,'drafts'=>$drafts,'source'=>$source,'draft'=>$draft,'history'=>$history,'canAdjust'=>$manager,'stale'=>$draft&&$source&&!hash_equals($draft['source_hash'],$source['hash'])];});}
}
